INSERT OR IGNORE INTO dnd35_feats
  (id,source_id,source_page,slug,name,description,rules_text,is_homebrew,owner_user_id,is_enabled,
   repeatable,choice_kind,repeatability_text,normal_text,special_text)
SELECT 'phb-feat-'||d.slug, s.id, d.source_page, d.slug, d.name, d.description, d.rules_text,
       0, NULL, 1, d.repeatable, d.choice_kind, d.repeatability_text, d.normal_text, d.special_text
FROM desired d CROSS JOIN dnd35_sources s
WHERE s.slug='players-handbook-3-5' AND s.owner_user_id IS NULL;
